class Solution {
    public int countMatchingSubarrays(int[] nums,int[] pattern){
        int answer=0;
        for(int start=0;start+pattern.length<nums.length;start++){
            boolean matches=true;
            for(int index=0;index<pattern.length;index++)if(Integer.compare(nums[start+index+1],nums[start+index])!=pattern[index]){
                matches=false;
                break;
            }
            if(matches)answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countMatchingSubarrays(nums:IntArray,pattern:IntArray):Int{
        var answer=0;
        for(start in 0 until nums.size-pattern.size){
            var matches=true;
            for(index in pattern.indices)if(nums[start+index+1].compareTo(nums[start+index])!=pattern[index]){
                matches=false;
                break
            };
            if(matches)answer++
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int countMatchingSubarrays(vector<int>& nums,vector<int>& pattern){
        int answer=0;
        for(int start=0;start+(int)pattern.size()<(int)nums.size();++start){
            bool matches=true;
            for(int index=0;index<(int)pattern.size();++index){
                int relation=(nums[start+index+1]>nums[start+index])-(nums[start+index+1]<nums[start+index]);
                if(relation!=pattern[index]){
                    matches=false;
                    break;
                }
            }
            answer+=matches;
        }
        return answer;
    }
};
